import{_ as e,c as r,o as i,ah as h}from"./chunks/framework.Dnh4IO1K.js";const _=JSON.parse('{"title":"第九卦 小畜 风天小畜 巽上乾下","description":"周易 - 第九卦 小畜 风天小畜 巽上乾下","frontmatter":{"title":"第九卦 小畜 风天小畜 巽上乾下","description":"周易 - 第九卦 小畜 风天小畜 巽上乾下"},"headers":[],"relativePath":"zh/classics/zhouyi/010.md","filePath":"zh/classics/zhouyi/010.md"}'),l={name:"zh/classics/zhouyi/010.md"};function t(n,a,s,d,o,c){return i(),r("div",null,[...a[0]||(a[0]=[h('<h1 id="小畜" tabindex="-1">小畜 <a class="header-anchor" href="#小畜" aria-label="Permalink to “小畜”">​</a></h1><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>亨。密云不雨，自我西郊。</p><h3 id="彖传" tabindex="-1">彖传 <a class="header-anchor" href="#彖传" aria-label="Permalink to “彖传”">​</a></h3><p>小畜；柔得位，而上下应之，曰小畜。健而巽，刚中而志行，乃亨。密云不雨，尚往也。自我西郊，施未行也。</p><h3 id="象传" tabindex="-1">象传 <a class="header-anchor" href="#象传" aria-label="Permalink to “象传”">​</a></h3><p>风行天上，小畜；君子以懿文德。</p><h3 id="初九" tabindex="-1">初九 <a class="header-anchor" href="#初九" aria-label="Permalink to “初九”">​</a></h3><p>复自道，何其咎，吉。象曰：复自道， 其义吉也。</p><h3 id="九二" tabindex="-1">九二 <a class="header-anchor" href="#九二" aria-label="Permalink to “九二”">​</a></h3><p>牵复，吉。象曰：牵复在中，亦不自失也。</p><h3 id="九三" tabindex="-1">九三 <a class="header-anchor" href="#九三" aria-label="Permalink to “九三”">​</a></h3><p>舆说辐，夫妻反目。象曰：夫 妻反目，不能正室也。</p><h3 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h3><p>有孚，血去惕出，无咎。象曰：有孚惕出，上合志也。</p><h3 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h3><p>有孚挛如，富以其邻。象曰：有孚挛如，不独富也。</p><h3 id="上九" tabindex="-1">上九 <a class="header-anchor" href="#上九" aria-label="Permalink to “上九”">​</a></h3><p>既雨既处，尚德载，妇贞厉。月几望，君子征凶。象曰：既雨既处，德积载也。君子征凶，有所疑也。</p>',19)])])}const b=e(l,[["render",t]]);export{_ as __pageData,b as default};
